mapper.select:
select *
from batch.workflow_definition

where tenant_id = #{tenantId}

    and workflow_code like concat('%', #{workflowCode}, '%')


    and workflow_name like concat('%', #{workflowName}, '%')


    and workflow_type = #{workflowType}


    and exists (
        select 1 from batch.workflow_node n
        where n.tenant_id = workflow_definition.tenant_id
          and n.workflow_definition_id = workflow_definition.id
          and n.related_job_code = #{relatedJobCode}
    )



        and single_job_definition_id is not null
        and single_job_definition_id is null



    and version = #{version}


    and enabled = #{enabled}

order by workflow_code, version desc, id desc

    limit #{pageRequest.pageSize} offset (#{pageRequest.pageNo} - 1) * #{pageRequest.pageSize}

select count(1)
from batch.workflow_definition

where tenant_id = #{tenantId}

    and workflow_code like concat('%', #{workflowCode}, '%')


    and workflow_name like concat('%', #{workflowName}, '%')


    and workflow_type = #{workflowType}


    and exists (
        select 1 from batch.workflow_node n
        where n.tenant_id = workflow_definition.tenant_id
          and n.workflow_definition_id = workflow_definition.id
          and n.related_job_code = #{relatedJobCode}
    )



        and single_job_definition_id is not null
        and single_job_definition_id is null



    and version = #{version}


    and enabled = #{enabled}

select *
from batch.workflow_definition
where tenant_id = #{tenantId}
  and workflow_code = #{workflowCode}
  and version = #{version}
limit 1

select *
from batch.workflow_definition
where tenant_id = #{tenantId}
  and id = #{id}
limit 1

select exists (
    select 1
      from batch.external_event_expectation_definition
     where tenant_id = #{tenantId}
       and workflow_definition_id = #{id}
) or exists (
    select 1
      from batch.file_group_expectation_definition
     where tenant_id = #{tenantId}
       and workflow_definition_id = #{id}
)

select *
from batch.workflow_definition
where tenant_id = #{tenantId}
  and single_job_definition_id = #{singleJobDefinitionId}
order by version desc, id desc
limit 1

mapper.delete:
delete from batch.workflow_definition
where tenant_id = #{tenantId}
  and id = #{id}

mapper.update:
update batch.workflow_definition
set enabled = #{enabled},
    updated_at = current_timestamp
where tenant_id = #{tenantId}
  and id = #{id}

update batch.workflow_definition
set schedule_enabled = #{scheduleEnabled},
    updated_at = current_timestamp
where tenant_id = #{tenantId}
  and id = #{id}
